function build(n,t,parent){const C=DATA.themes[t],color=v=>C[v]||v;let node;if(n.type==='text'){node=figma.createText();node.fontName={family:'Inter',style:({400:'Regular',500:'Medium',600:'Semi Bold',700:'Bold'})[n.weight]};node.characters=n.text;node.fontSize=n.size;node.lineHeight={unit:'PERCENT',value:(n.line||1.4)*100};node.letterSpacing={unit:'PIXELS',value:n.tracking||0};node.fills=[{type:'SOLID',color:rgb(color(n.color))}];if(n.strike)node.textDecoration='STRIKETHROUGH';node.textAutoResize='WIDTH_AND_HEIGHT';if(n.w){node.resize(n.w,n.h||node.height);node.textAutoResize=n.h?'NONE':'HEIGHT';}}else if(n.type==='icon'){node=figma.createNodeFromSvg('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="'+color(n.color)+'" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+DATA.svgPaths[n.kind]+'</svg>');node.resize(n.w,n.h);}else if(n.type==='image'){node=figma.createRectangle();if(!imageCache[n.src])imageCache[n.src]=figma.createImage(figma.base64Decode(IMAGES[n.src])).hash;node.resize(n.w,n.h);node.fills=[{type:'IMAGE',imageHash:imageCache[n.src],scaleMode:'FIT'}];}else{node=figma.createFrame();node.layoutMode=n.dir==='row'?'HORIZONTAL':'VERTICAL';node.primaryAxisSizingMode=(n.dir==='row'?n.w:n.h)?'FIXED':'AUTO';node.counterAxisSizingMode=(n.dir==='row'?n.h:n.w)?'FIXED':'AUTO';node.primaryAxisAlignItems=n.justify==='center'?'CENTER':'MIN';node.counterAxisAlignItems=n.align==='center'?'CENTER':'MIN';node.itemSpacing=n.gap||0;const p=n.padding||0;node.paddingTop=node.paddingBottom=Array.isArray(p)?p[0]:p;node.paddingLeft=node.paddingRight=Array.isArray(p)?p[1]:p;node.fills=n.bg?[{type:'SOLID',color:rgb(color(n.bg))}]:[];node.cornerRadius=n.radius||0;if(n.border){node.strokes=[{type:'SOLID',color:rgb(C.line)}];node.strokeWeight=1;}node.clipsContent=!!n.clip;if(n.w||n.h){node.resize(n.w||1,n.h||1);node.primaryAxisSizingMode=(n.dir==='row'?n.w:n.h)?'FIXED':'AUTO';node.counterAxisSizingMode=(n.dir==='row'?n.h:n.w)?'FIXED':'AUTO';}}parent.appendChild(node);node.name=n.name;created.push(node.id);if(n.grow)node.layoutGrow=1;for(const child of n.children||[])build(child,t,node);return node;}
const roots=[];for(let i=0;i<DATA.scenes.length;i++){const s=DATA.scenes[i];const old=page.children.find(x=>x.name===s.name);if(old)throw new Error('Exploration already exists: '+s.name);const n=build(s,s.theme,page);n.x=i<2?(i===0?0:1520):(i===2?0:1520);n.y=i<2?0:2400;roots.push({id:n.id,name:n.name,width:n.width,height:n.height});}figma.viewport.scrollAndZoomIntoView(roots.map(x=>page.findOne(n=>n.id===x.id)));return {createdNodeIds:[page.id,...created],screens:roots};